      "canonicalText": "商君曰：「前世不同教，何古之法？帝王不相復，何禮之循？伏羲、神農，教而不誅；黃帝、堯、舜，誅而不怒；及至文、武，各當時而立法，因事而制禮。禮、法以時而定，制、令各順其宜，兵甲器備各便其用。臣故曰：『治世不一道，便國不必法古。』湯、武之王也，不循古而興；殷、夏之滅也，不易禮而亡。然則反古者未可非，而循禮者未足多也。君無疑矣。」",
