      "readingAid": {
        "translation": "商鞅嚴正駁斥道：「上古歷代先賢的社會教化各不相同，究竟應當去效法哪一個古代呢？歷代開國帝王制度從不機械重複照搬（不相復），究竟應當去遵循哪一家的舊禮呢？\\n\\n伏羲與神農時代，以道德教化天下而不隨意誅殺（教而不誅）；黃帝與堯舜時代，依法誅伐罪魁而不夾帶私怒動氣（誅而不怒）；及至周文王與周武王時代，皆各自順應所處時代的具體需要而創立法度，因應現實事變而制定禮樂！\\n\\n禮儀法度必須順應時代變遷而確立（以時而定），體制法令必須各隨其適宜而調整，軍隊兵甲武器裝備必須各隨其實用便利而製造！所以臣才說：『治理天下從來沒有一成不變的唯一道路，只要能使國家富強興旺就絕不必盲目效法古代（治世不一道，便國不必法古）！』\\n\\n商湯與周武王成就天下王業，正是因為不墨守成規遵從舊古而開創新朝；殷商與夏朝之所以走向覆滅，正是因為死守舊禮不加變更改革而自取滅亡！既然如此，那麼反思改革古法的人絕不可被非難責備，而一味死守舊禮成規的人也根本不值得讚美推崇！請君上切勿再有任何猶豫疑慮！」",
        "analysis": "【題解與背景】\\n本段選自《商君書》〈更法〉第 6 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「商君曰前世不同教何古之法帝王不相復何禮之循伏……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「商」、「君」、「前」、「世」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《商君書》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
      },
