      "analysis": "【題解與治世不一道便國不必法古商湯周武不循古而興商鞅歷史進化論】中國歷史上最震撼的歷史哲學宣言——「治世不一道，便國不必法古」，以夏商周三代興亡史為證，雄辯論證制度必須因時因事而變革進化。\\n【詞義訓詁】「不相復」：不重複照搬；「便國」：使國家富強得利；「未足多」：多，稱讚讚美；不值得稱道。"
