      "canonicalText": "商君曰：「臣聞之：『疑行無成，疑事無功。』君亟定變法之慮，殆無顧世俗之議也。且夫有高人之行者，固見負於世；有獨智之慮者，必見敖於民。語曰：『愚者闇於成事，知者見於未萌。民不可與慮始，而可與樂成。』郭偃之法曰：『論至德者，不和於俗；成大功者，不謀於眾。』法者，所以愛民也；禮者，所以便事也。是以聖人苟可以強國，不法其故；苟可以利民，不循其禮。孝公曰：「善。」",
