        "translation": "商鞅進一步進言道：「臣聽說過：『行事猶豫不決就絕不可能取得成功（疑行無成），決策狐疑動搖就絕不可能建立大功（疑事無功）！』請君上迅速敲定變法大計的決策考慮，絕不可顧忌世俗平庸之人的風言風語與非議！\\n\\n況且具備超越常人崇高品行的人，本來就注定會被世俗平庸之輩所背棄誤解（見負於世）；具備獨到深邃智慧謀略的人，必定會遭受無知百姓的嘲弄譏諷（見敖於民）。\\n\\n古諺語說道：『愚昧無知的人在事情已經成功擺在眼前時依然昏暗不明（愚者闇於成事），明智卓越的智者在事態尚未萌芽之際就早已洞燭先機（知者見於未萌）。對於廣大普通民眾，在創業艱難剛開始之際是不可以與之共同謀劃籌謀的，但等到事業大功告成之時卻可以與他們共同享受太平福祉（民不可與慮始，而可與樂成）！』\\n\\n晉國名臣郭偃的法治箴言說：『探討至高道德大業的人，絕不會苟同迎合世俗流俗（不和於俗）；成就蓋世偉大功業的人，絕不會與泛泛庸眾商議謀劃（不謀於眾）！』\\n\\n法律法度，本是用來愛護保護百姓根本利益的（所以愛民）；禮儀制度，本是用來便利推動天下事業的（所以便事）！因此得道的聖人只要能夠使國家富強興盛，就絕不墨守舊有規章（不法其故）；只要能夠使人民獲得切實利益，就絕不死守舊有禮節（不循其禮）！」秦孝公由衷讚許道：「說得太好了！」",
