        "translation": "大凡國家君王用來勉勵激勵百姓的根本手段，在於官位與爵位（官爵也）；而國家賴以繁榮興盛的根本支柱，在於農業生產與軍事作戰（農戰也）！如今社會上的民眾謀求官職爵位，如果全都不依靠辛勤務農與臨陣殺敵（不以農戰），而是依靠投機取巧的虛浮言辭與空洞學說（巧言虛道），這就叫做勞民傷財的疲敝之民（勞民）。充滿疲敝之民的國家，國力必定虛弱無力；國力虛弱無力的國家，其疆土必定會被敵國割裂削弱（必削）！",
