      "order": 11,
      "canonicalText": "詩、書、禮、樂、善、修、仁、廉、辯、慧，國有十者，上無使守戰。國以十者治，敵至必削，不至必貧。國去此十者，敵不敢至；雖至，必卻；興兵而伐，必取；按兵不伐，必富。國好力者，曰「以難攻」，以難攻者必興；好辯者，曰「以易攻」，以易攻者必危。故聖人明君者，非能盡其萬物也，知萬物之要也。故其治國也，察要而已矣。",
