      "canonicalText": "今為國者多無要。朝廷之言治也，紛紛焉務相易也。是以其君惛於說，其官亂於言，其民惰而不農。故其境內之民，皆化而好辯樂學，事商賈，為技藝，避農戰，如此則亡國不遠矣。國有事，則學民惡法，商民善化，技藝之民不用，故其國易破也。",
