      "translation": "從事農業生產的人口稀少，而游手好閒不勞而獲的寄生食客眾多（遊食者眾），所以這個國家必定貧困交加陷入危亡！\\n\\n田野中的螟蛉、蟊賊等害蟲春生秋死，只要爆發一次蟲災天下百姓就會面臨數年的糧食匱乏；如今社會上一人辛勤耕田種地，卻有一百個不事生產的人坐享其成吃白食，這群寄生蟲對國家的禍害比起田間害蟲不知要巨大多少倍啊！這時候縱然家家戶戶都藏有一捆《詩》《書》典籍（鄉一束家一員），對於拯救天下大治也絲毫沒有任何用處，根本不是扭轉國家危局的良策！\\n\\n所以古代聖王扭轉乾坤的唯一出路在於全面回歸農戰！古訓說道：一百個人從事農業生產、只有一個人脫產閒居（百人農一人居），這個國家就能稱王天下；十個人從事農業生產、只有一個人脫產閒居，這個國家就能成為天下強國；如果一半人務農而另一半人全都不事生產脫產閒居（半農半居），這個國家就必定大難臨頭陷入危亡！",
