      "readingAid": {
        "translation": "所以治理國家的聖明君主務必使全體人民歸心於農業生產！國家如果放棄農業，那麼在與天下諸侯爭奪霸權之際就根本無法自立自持，國家的整體人力物力實力就必定極度不足！因此列國諸侯就會趁機攻擊打擊它的薄弱環節（撓其弱），乘著它的衰敗大舉進犯，國土被割裂侵吞而一蹶不振，到那時就再也後悔莫及了！\\n\\n聖人深刻知曉治國的根本要領，所以引導全體百姓全心全意歸心於農業。百姓歸心於農業，民風就會淳樸質樸而且容易引導端正（民樸而可正）；如果民心浮躁紛繁多變，就難以驅使調動；百姓真誠守信，就可以依託他們進行堅守與作戰（可以守戰）；心志專一於農戰，民眾就會減少奸詐狡猾而且安土重遷（重居）；心志專一，朝廷就能運用明確的賞罰來激勵他們奮勇前進；心志專一，國家就能在對外作戰中充分發揮其無敵的戰鬥力（可以外用）！",
        "analysis": "【題解與背景】\\n本段選自《商君書》〈農戰〉第 44 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「故治國者欲民之農也國不農則與諸侯爭權不能自持……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「治」、「國」、「欲」、「民」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《商君書》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
      },
      "translation": "所以治理國家的聖明君主務必使全體人民歸心於農業生產！國家如果放棄農業，那麼在與天下諸侯爭奪霸權之際就根本無法自立自持，國家的整體人力物力實力就必定極度不足！因此列國諸侯就會趁機攻擊打擊它的薄弱環節（撓其弱），乘著它的衰敗大舉進犯，國土被割裂侵吞而一蹶不振，到那時就再也後悔莫及了！\\n\\n聖人深刻知曉治國的根本要領，所以引導全體百姓全心全意歸心於農業。百姓歸心於農業，民風就會淳樸質樸而且容易引導端正（民樸而可正）；如果民心浮躁紛繁多變，就難以驅使調動；百姓真誠守信，就可以依託他們進行堅守與作戰（可以守戰）；心志專一於農戰，民眾就會減少奸詐狡猾而且安土重遷（重居）；心志專一，朝廷就能運用明確的賞罰來激勵他們奮勇前進；心志專一，國家就能在對外作戰中充分發揮其無敵的戰鬥力（可以外用）！",
      "analysis": "【題解與令民歸心於農民樸可正重居守戰以難攻取外用治民歸農之利】系統闡述引導民眾歸心農業的多重戰略收益——民風淳樸、安土重遷、信守不欺、便於賞罰調動，為對外爭霸奠定堅實基本盤。"
