      "readingAid": {
        "translation": "大凡治理國家的統帥，最憂慮擔憂的就是人心渙散、民眾力量如同散沙無法凝聚團結（不可搏也）；因此得道的聖人創立推行專注於農戰的「作壹」大法，用以把全體人民的力量緊緊凝聚團結在一起（摶之也）！\\n\\n國家推行農戰「作壹」堅持一年，就能保持十年的強盛無敵；推行「作壹」堅持十年，就能保持百年的繁榮富強；推行「作壹」堅持百年，就能保持千年的霸業強盛；能夠保持千年強盛不衰的國家，就必定能統一天下成就天下王者大業（王）！",
        "analysis": "【訓詁與名物】「散」渙散，指民眾心思分散，各行其是。「搏」同「摶」，凝聚、捏合。「作壹」使民眾的目標和行為專一，在《商君書》中特指專注於農業和戰爭（農戰）。\\n【章法與結構】本段以「患民散」引出「作壹」的必要性，隨後用「一歲、十歲、百歲」的排比句式，層層遞進，極言「作壹」所帶來的長遠政治回報，氣勢磅礡。\\n【思想與義理】此章是商鞅法家思想中「統一意志」的核心論述。在法家看來，民眾如果擁有多元化的追求（如經商、遊說、求學），國家的力量就會被分散，無法應對殘酷的兼併戰爭。因此，統治者必須通過制度設計，將民眾的上升通道（爵祿）嚴格限制在「農」與「戰」這兩個領域（作壹），從而將全社會的人力資源像捏泥巴一樣死死地凝聚在一起（摶）。商鞅認為，這種制度的執行時間越長，國家的戰爭潛力就越大，最終必然能成就帝王霸業。這是一種極端追求國家動員能力的軍國主義思想。"
      },
