      "readingAid": {
        "translation": "企圖單純依仗外在剛暴力量去消除國內豪強頑疾的，國家反而會走向衰弱（以強去強者弱）；善於運用法治柔道與微細刑律去化解消除強橫勢力的，國家才能真正實現強盛（以弱去強者強）！國家如果一味宣揚姑息寬仁之善（國為善），奸邪作惡之徒就必定氾濫成災；國家物資富足而引導民眾安於儉樸（國富而貧），國家就能實現長治久安；國家財政貧弱而民眾生活放蕩奢靡（國貧而富），社會就必定陷入動盪動亂！國家一旦面臨外敵入侵爆發戰事：清談文人厭惡國家嚴厲軍法，經商之人善於投機變節逃亡，身懷雜藝之人在戰場上毫無實用價值，所以這樣的國家極其容易被敵國擊破！",
        "analysis": "【主題與背景】本段選自《商君書・去強》。清除社會寄生階層與私門勢力，消除六蠹，建立嚴密的國家統治與集權秩序。歷史上記錄了秦國實行法家變法、走向中央集權與帝國統一的理論與制度建構。\\n【詞義與名物】段落中涵括「去強」相關關鍵名詞，如「法」、「信」、「權」、「耕戰」、「錯法」、「壹賞」等，體現秦國法律體系精密的制度設計。\\n【思想與篇章】《商君書》此段強調「法者，國之權衡也」，通過嚴密法律與權力集中，打破舊貴族世襲特權，將國家資源全數注入農耕與軍事，為戰國時期法家變法實踐提供了深刻的戰略引領。"
      },
      "translation": "企圖單純依仗外在剛暴力量去消除國內豪強頑疾的，國家反而會走向衰弱（以強去強者弱）；善於運用法治柔道與微細刑律去化解消除強橫勢力的，國家才能真正實現強盛（以弱去強者強）！國家如果一味宣揚姑息寬仁之善（國為善），奸邪作惡之徒就必定氾濫成災；國家物資富足而引導民眾安於儉樸（國富而貧），國家就能實現長治久安；國家財政貧弱而民眾生活放蕩奢靡（國貧而富），社會就必定陷入動盪動亂！國家一旦面臨外敵入侵爆發戰事：清談文人厭惡國家嚴厲軍法，經商之人善於投機變節逃亡，身懷雜藝之人在戰場上毫無實用價值，所以這樣的國家極其容易被敵國擊破！",
      "analysis": "【題解與去強篇開篇以弱去強國為善姦必多國富而貧則治法家辯證法】《商君書》（去強第四）開篇——提出「以弱去強」的法治辯證法，批判姑息之善反生奸邪，確立「藏富於國、引導民儉、消除空談」之治國原則。\\n【詞義訓詁】「以弱去強」：弱指嚴細法度與制度約束；強指桀驁不馴之強宗豪右；「國富而貧」：國家資財充裕而人民保持勤儉質樸。"
