        "translation": "依法實施嚴格嚴厲的刑罰而審慎克制地施加獎賞（重罰輕賞），這說明朝廷在真正深層愛護保護萬民（使民不犯法），百姓就會在戰場上為君王捨生忘死（民死上）；如果濫施豐厚獎賞而對違法過失輕描淡寫姑息放任（重賞輕罰），這說明朝廷並未真正保護愛護萬民（縱民為惡），百姓在戰場上就絕不會為君王拼死效命！\\n\\n振興崛起的國家推行刑罰，百姓既能從中獲得免於被侵害的切實利益又對法律心懷敬畏（民利且畏）；推行獎賞，百姓既能獲得功名利益又對君王由衷愛戴（民利且愛）。國家缺乏堅實的耕戰硬實力，而企圖依靠虛浮智謀機巧去爭霸的，必定走向滅亡！",
