      "readingAid": {
        "translation": "國家推行農戰「作壹」堅持一年，就能保持十年的強大；堅持十年，就能保持百年的富強；堅持百年，就能保持千年的繁榮；保持千年強盛不衰的國家，就必定能稱王天下！\\n\\n國家如果只能在國內生產積蓄充沛的人力物力實力（能生），卻不懂得在戰場上消滅敵軍有生力量並釋放轉化本國過剩能量（不能殺），這叫做「內部自我消耗崩潰的國家（自攻之國）」，其國力必定會被削弱割地；國家既善於組織生產積累實力（能生），又善於在對外作戰中攻伐敵國摧毀強敵（能殺），這叫做「對外開疆拓土的強盛國家（攻敵之國）」，其國家就必定無比強大！",
        "analysis": "【題解與背景】\\n本段選自《商君書》〈去強〉第 55 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「國作壹一歲十歲強作壹十歲百歲強作壹百歲千歲強……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「國」、「作」、「壹」、「一」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《商君書》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
      },
      "translation": "國家推行農戰「作壹」堅持一年，就能保持十年的強大；堅持十年，就能保持百年的富強；堅持百年，就能保持千年的繁榮；保持千年強盛不衰的國家，就必定能稱王天下！\\n\\n國家如果只能在國內生產積蓄充沛的人力物力實力（能生），卻不懂得在戰場上消滅敵軍有生力量並釋放轉化本國過剩能量（不能殺），這叫做「內部自我消耗崩潰的國家（自攻之國）」，其國力必定會被削弱割地；國家既善於組織生產積累實力（能生），又善於在對外作戰中攻伐敵國摧毀強敵（能殺），這叫做「對外開疆拓土的強盛國家（攻敵之國）」，其國家就必定無比強大！",
      "analysis": "【題解與能生不能殺自攻之國能生能殺攻敵之國國家能量釋放與轉化論】先秦最深刻的國家總體戰理論——「生（經濟生產積蓄）」與「殺（軍事作戰釋放）」的辯證平衡，防止內部能量過剩引發內耗，以攻敵開拓成就強國。"
