      "readingAid": {
        "translation": "天下百姓本能的心理本是渴望安寧大治的（民情治），然而其日常行為卻往往容易誘發爭端混亂（事亂）。\\n\\n所以在推行法律刑罰時，必須對微小的違法過失給予嚴肅重判懲戒（重其輕者）；微小的過失犯罪如果不敢滋生發生，那麼重大的惡性犯罪就根本沒有機會產生了（重者無從至）！這就叫做在秩序井然大治之時就預先防微杜漸化解隱患（治之於其治）！\\n\\n如果在實施刑罰時，只對重大罪行予以重判、而對微小過失輕描淡寫予以縱容（重其重者輕其輕者），等到惡性案件頻發時才手忙腳亂去鎮壓，這就叫做在社會已經陷入大亂之際才被動治理（治之於其亂）！\\n\\n所以對輕罪實施嚴懲，就能徹底消除刑罰犯罪、順利成就天下大業（刑去事成）；如果只對重罪重判而放任輕罪，那麼刑罰判決越是繁重、違法犯罪的事端反而越發層出不窮（刑至事生）！",
        "analysis": "【題解與背景】\\n本段選自《商君書》〈說民〉第 66 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「民之情也治其事也亂故行刑重其輕者輕者不生則重……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「民」、「情」、「治」、「事」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《商君書》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
      },
