      "analysis": "【題解與行刑重其輕者輕者不生重者無從至治之於其治防微杜漸以刑去刑】商鞅最核心的刑法學理論——「重其輕者（嚴懲輕罪）」，抓小防大、消滅犯罪萌芽，實現「刑去事成、以刑去刑」之終極法治目標。"
