        "translation": "人民如果生活極度貧困國家動員實力就會衰竭（民貧則弱），民間如果過度暴富奢靡社會風氣就會放蕩淫逸（國富則淫）；放蕩淫逸就會滋生不勞而獲的蛀蟲蝨官，蛀蟲橫行國家就必定走向衰弱！\\n\\n所以對於貧困怠惰之人，用嚴格的農戰刑律去督促驅使他們勤勉耕作，他們就能脫貧致富（貧者富）；對於家資富足之人，引導他們通過上繳糧食或捐資報國來換取朝廷爵位（損之以賞），使其財富轉化為國家戰備實力（富者貧）！\\n\\n治理國家的宏觀調控大計，最寶貴的就是善於調節社會財富分配：使貧困之人通過辛勤耕戰轉化為富裕自耕農（令貧者富），使豪富之人通過回報國家避免奢靡腐化（富者貧）；貧者能富、富者轉化，國家就必定無比強大！",
        "analysis": "【題解與背景】\\n本段選自《商君書》〈說民〉第 68 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「民貧則弱國富則淫淫則有蝨有蝨則弱故貧者益之以……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「民」、「貧」、「弱」、「國」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《商君書》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
