      "readingAid": {
        "translation": "聖人並不是試圖用世人認為輕鬆容易的投機手段（世之所易），去克服戰勝世間艱難複雜的歷史大局；而是必定依靠踏踏實實從事最艱苦卓絕的基礎建設（必以其所難），去從容碾壓戰勝那些投機取巧的對手！\\n\\n所以當天下民風質樸愚純之時，憑藉卓越的智慧就能稱王天下；當世人全都自作聰明機巧氾濫之時，唯有依靠堅不可摧的實力耕戰才能稱王天下（力可以王）！世人自作聰明就會滋生機巧，機巧氾濫就會產生偽善，偽善橫行就會演變為欺詐。所以企圖依靠虛浮智謀巧詐去治理天下的，天下必定陷入大亂；依靠堅實硬實力與嚴明法治去治理天下的，國家必定實現天下大治！",
        "analysis": "【題解與背景】\\n本段選自《商君書》〈算地〉第 81 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「聖人非能以世之所易勝其所難也必以其所難勝其所……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「聖」、「人」、「非」、「能」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《商君書》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
      },
