      "analysis": "【題解與必以其所難勝其所易以力治世者治硬實力破除機巧詐偽】提出「以其所難勝其所易」的戰略攻堅原則，指出在機巧詐偽的亂世中唯有依仗堅實實力與法治方能定紛止爭。"
