      "readingAid": {
        "translation": "依託於本土土地從事農業耕作民風就會淳樸質樸（資於地則樸），將前途寄託於外國投機冒險民心就會陷入困惑動搖（託危於外則惑）。百姓在國內安心務農心性質樸，接觸外國投機風氣就會產生困惑；所以應當使百姓勤勉務農而作戰時恪守紀律勇敢整肅（戰戢）。\\n\\n百姓勤勉務農那麼積蓄的家產財富就必定沉重豐厚（資重），作戰勇敢整肅那麼鄰近敵國就必定面臨覆滅危機（鄰危）。家產財富沉重豐厚老百姓就不可能輕易背負逃亡，鄰國陷入危亡老百姓就絕不會盲目投奔一無所有的絕境。放著本國安居樂業的豐厚財產不要而去投奔危亡的外國，這是連瘋癲狂夫都不會去做的愚蠢蠢事啊！",
        "analysis": "【訓詁與名物】「資於地」將財產和精力投入土地。「樸」淳樸、老實、安分守己。「託危於外」將希望寄託在國外的投機活動上。「惑」狡猾、心思活絡、不安分。「戰戢」戢讀ㄐㄧˊ，這裡通「愻」或「捷」，指在戰爭中勇猛克敵。「資重」家產豐厚。「負」背負。\\n【章法與結構】這是一段邏輯極其嚴密的政治心理學分析。通過「資於地」與「託於外」的對比，推導出「農勉」和「戰戢」的雙重效果，最後用「狂夫不為」收尾，證明了這套制度對民眾行為的絕對控制力。\\n【思想與義理】此章深刻揭示了商鞅「重農」政策背後隱藏的「愚民與控民」邏輯。在商鞅看來，讓民眾種地的根本目的不僅僅是為了生產糧食，更是為了「把民眾拴在土地上」。土地是搬不走的重資產。一旦民眾把一生的心血都投入到土地中（資重），他們就會變得安分守己（樸），因為他們害怕失去這一切。同時，由於秦國軍隊的強悍讓周邊鄰國都處於危險之中，民眾就算想逃跑，也無處可去（因為跑到危險的敵國去等於找死，而且也帶不走土地）。這樣，通過經濟利益的捆綁（土地）和外部環境的威懾（戰爭），統治者就徹底鎖死了民眾的逃生通道，讓他們只能乖乖地為君主種地和打仗。這是一種極其冷酷而有效的專制統治術。"
      },
      "translation": "依託於本土土地從事農業耕作民風就會淳樸質樸（資於地則樸），將前途寄託於外國投機冒險民心就會陷入困惑動搖（託危於外則惑）。百姓在國內安心務農心性質樸，接觸外國投機風氣就會產生困惑；所以應當使百姓勤勉務農而作戰時恪守紀律勇敢整肅（戰戢）。\\n\\n百姓勤勉務農那麼積蓄的家產財富就必定沉重豐厚（資重），作戰勇敢整肅那麼鄰近敵國就必定面臨覆滅危機（鄰危）。家產財富沉重豐厚老百姓就不可能輕易背負逃亡，鄰國陷入危亡老百姓就絕不會盲目投奔一無所有的絕境。放著本國安居樂業的豐厚財產不要而去投奔危亡的外國，這是連瘋癲狂夫都不會去做的愚蠢蠢事啊！",
      "analysis": "【題解與資於地則樸資重不可負而逃戰戢鄰危安土重遷經濟學】以土地資產的沉澱性（資重）論述增強國民向心力與防範流亡的深層經濟學機制，使民安居樂業、誓死衛國。"
