      "readingAid": {
        "translation": "因此得道聖人治理國家：深刻觀察世俗民情而制定相應法度國家就能實現大治（觀俗立法則治），深入考察國家實情而確立根本本業國家就能完全切合時宜（察國事本則宜）。如果不觀察時代風俗、不考察國家根本，那麼法令法規縱然確立了百姓也會陷入混亂，政務雖然無比繁劇勞累而實際成效卻極其微薄寡少（事劇而功寡），這正是臣所指出的最嚴重治國過失啊！",
        "analysis": "【訓詁與名物】「觀俗」觀察社會的風俗習慣。「事本」國家的根本事業，對商鞅來說就是農戰。「宜」適宜、得當。「事劇」政務繁忙、勞神費力。「功寡」成效很少。「過」過失、錯誤。\\n【章法與結構】本段採用了正反對比的論證方法。前半段論述「觀俗察本」的正面效果（治、宜），後半段論述盲目立法的反面後果（民亂、功寡），邏輯清晰，論點明確。\\n【思想與義理】此章體現了法家在制度設計上極強的「現實主義和經驗主義」色彩。與儒家喜歡引經據典、盲目崇拜古代先王之法不同，法家堅決主張「法與時轉則治」。商鞅認為，法律和政策絕對不能脫離具體的社會現實。統治者在制定法律之前，必須進行深入的社會調查，了解當前民眾的心理狀態（觀俗）和國家面臨的最大挑戰（察國本）。如果脱離了這些現實基礎，憑空捏造出一套法律（如在戰國時代去推行西周的禮樂制度），那只會是南轅北轍，政府每天忙得焦頭爛額（事劇），卻解決不了任何實際問題，甚至會引發社會動盪（民亂）。這是一種非常務實的政治認識論。"
      },
