      "analysis": "【題解與觀俗立法察國事本因地制宜實事求是立法學綱領】法家實事求是的立法學原則——「觀俗立法、察國事本」，反對主觀脫離實際的盲目立法導致「事劇功寡」，確立因時順勢的法治演進觀。"
