      "canonicalText": "夫刑者所以禁邪也；而賞者， Linux所以助禁也。羞辱勞苦者，民之所惡也；顯榮佚樂者，民之所務也。故其國刑不可惡而爵祿不足務也，此亡國之兆也。刑人復漏，則小人辟淫而不苦刑，則徼倖於民上。徼倖於民上以利求，顯榮之門不一，則君子事勢以成名。小人不避其禁，故刑煩；君子不設其令，則罰行。刑煩而罰行者，國多姦；國多姦則富者不能守其財，而貧者不能事其業，田荒而國貧。",
