      "canonicalText": "田荒則民詐生，國貧則上匱賞。故聖人之為治也，刑人無國位，戮人無官任。刑人有列，則君子下其位；戮人衣錦食肉，則小人冀其利。君子下其位，則羞功；小人冀其利，則伐姦。故刑戮者，所以止姦也；而官爵者，所以勸功也。",
