      "readingAid": {
        "translation": "農田荒蕪廢棄那麼民間欺詐詐偽就會層出不窮，國家財政貧困那麼朝廷上級就缺乏足夠物資來兌現獎賞。所以聖人主持國家治理：受過刑罰懲處的罪犯絕對不准享有國家爵位，遭受刑戮之人絕對不准出任各級官職！\\n\\n如果受過刑罰的人竟然也能位列朝堂享有官位，那麼正派君子就會以與之同列為恥而主動辭官退位；如果犯罪受戮之人竟然能夠身穿錦緞華服、大魚大肉享受富貴，那麼市井小人就會心生僥倖企圖通過犯罪牟取暴利！正派君子退位就會使全社會羞於立功，市井小人企圖牟利就會使作惡奸邪受到誇耀鼓勵！所以嚴刑處罰本是用來制止奸邪的，而官職爵位本是用來勉勵戰功的！",
        "analysis": "【訓詁與名物】「詐生」產生狡詐投機之心。「匱賞」缺乏賞賜的物資。「刑人、戮人」受過刑罰、被處罰過的人。「列」朝廷的班列、爵位。「下其位」鄙視自己的職位，覺得可恥。「衣錦食肉」穿著錦緞，吃著肉，形容生活奢華。「冀」企圖、希求。「羞功」以立功為恥。「伐姦」誇耀自己的姦詐手段。「勸」鼓勵。\\n【章法與結構】這是一段邏輯推演極其精彩的論述。從經濟基礎（田荒國貧）切入，轉入對「賞罰分明」的論述。通過正反假設，詳細推導了「刑人居高位」對君子和小人兩種截然不同的人群所產生的破壞性心理影響，最後精準地總結了刑與賞的本質功能。\\n【思想與義理】此章深刻闡述了法家關於「政治榮譽感與激勵機制」的核心理論。商鞅指出，國家的爵位和官職不僅僅是權力的象徵，更是國家價值觀的風向標。如果法律被破壞，讓那些犯過罪、投機取巧的人（刑戮人）竊取了高官厚祿，這將對社會造成毀滅性的雙重打擊：一方面，它會摧毀精英階層（君子）的榮譽感，讓他們覺得為國家效力是一種恥辱，從而發生「劣幣驅逐良幣」的現象；另一方面，它會給底層民眾（小人）樹立一個極壞的榜樣，讓他們認為只要膽子大、夠姦詐就能發財升官。因此，賞罰必須絕對分明：刑罰必須讓壞人身敗名裂，官爵必須只給那些真正為國家立功（農戰）的人。這才能保證國家機器的健康運轉。"
      },
      "translation": "農田荒蕪廢棄那麼民間欺詐詐偽就會層出不窮，國家財政貧困那麼朝廷上級就缺乏足夠物資來兌現獎賞。所以聖人主持國家治理：受過刑罰懲處的罪犯絕對不准享有國家爵位，遭受刑戮之人絕對不准出任各級官職！\\n\\n如果受過刑罰的人竟然也能位列朝堂享有官位，那麼正派君子就會以與之同列為恥而主動辭官退位；如果犯罪受戮之人竟然能夠身穿錦緞華服、大魚大肉享受富貴，那麼市井小人就會心生僥倖企圖通過犯罪牟取暴利！正派君子退位就會使全社會羞於立功，市井小人企圖牟利就會使作惡奸邪受到誇耀鼓勵！所以嚴刑處罰本是用來制止奸邪的，而官職爵位本是用來勉勵戰功的！",
      "analysis": "【題解與刑人無國位戮人無官任嚴肅官爵純潔性確立價值導向】強調官爵與刑罰的涇渭分明——嚴禁罪犯買官混入統治階層，保護立功君子的崇高尊嚴，杜絕小人僥倖心理。"
