      "canonicalText": "今國立爵而民羞之，設刑而民樂之，此蓋法術之患也。故君子操權一政以立術，立官貴爵以稱之，論勞舉功以任之，則是上下之稱平。上下之稱平，則臣得盡其力，而主得專其柄。",
