      "readingAid": {
        "translation": "如今列國設立了爵位而百姓卻因其貶值腐敗而感到羞恥，設立了刑罰而奸邪之徒卻因其鬆弛而樂於鑽營，這完全是制度法術混亂所招致的嚴重禍患啊！\\n\\n所以聖明君王牢牢掌控最高權力、統一國家政令以確立根本法術體系，設立嚴明官職、抬高爵位尊嚴使之名實相符，根據實際功勞與實幹戰功來考核選拔任用人才，這樣君臣上下之間的權責標準就能達到高度公平平衡（上下之稱平）！上下標準公平平衡，那麼全體臣民就能竭盡全力為國效命，而君王就能牢牢獨掌統御國家的至高權柄！",
        "analysis": "【訓詁與名物】「羞之」以之為恥。「樂之」樂於觸犯，不以為恥。「法術之患」推行法治的策略和手段出了弊病。「一政」統一政令。「術」統治的方法、手段。「稱之」稱讀ㄔㄥˋ，相稱、匹配。「論勞舉功」根據功勞的大小來選拔和任用。「稱平」名實相符，權限與責任平衡。「專其柄」專獨掌控國家的權柄。\\n【章法與結構】本段以一個極其反常的社會現象（羞爵樂刑）破題，點出當時政治的病根（法術之患）；隨後開出法家的藥方（操權一政，論勞舉功），最後描繪了治國的理想狀態（臣盡力，主專柄）。\\n【思想與義理】此章直指政治管理中「激勵機制失效」的痛點。如果一個國家的榮譽系統崩潰了（如買官賣官、賞賜不公），民眾就會對國家的爵位嗤之以鼻（羞爵）；如果國家的法律形同虛設（如法不責眾、權貴法外狂徒），民眾就不會對刑罰產生敬畏（樂刑）。商鞅認為，解決這個問題的唯一辦法，就是君主必須把「官爵」和「刑罰」這兩把利器牢牢地抓在自己手裡，並且建立一套絕對客觀、只看結果的績效考核制度（論勞舉功）。誰立了軍功，不管出身多卑微，就給他升官發財；誰犯了法，不管地位多高，就嚴懲不貸。只有讓「名（官爵）」與「實（功勞）」絕對相稱，臣子才會有動力去賣命，君主的權力也才能得到最大的鞏固。這體現了法家極其冷酷而理性的權力邏輯。"
      },
      "translation": "如今列國設立了爵位而百姓卻因其貶值腐敗而感到羞恥，設立了刑罰而奸邪之徒卻因其鬆弛而樂於鑽營，這完全是制度法術混亂所招致的嚴重禍患啊！\\n\\n所以聖明君王牢牢掌控最高權力、統一國家政令以確立根本法術體系，設立嚴明官職、抬高爵位尊嚴使之名實相符，根據實際功勞與實幹戰功來考核選拔任用人才，這樣君臣上下之間的權責標準就能達到高度公平平衡（上下之稱平）！上下標準公平平衡，那麼全體臣民就能竭盡全力為國效命，而君王就能牢牢獨掌統御國家的至高權柄！",
      "analysis": "【題解與操權一政以立術論勞舉功上下稱平算地篇大結尾】《算地篇》圓滿總結——確立「集權一政、論功任官、上下稱平」之法家制度基石，實現臣盡其力、主專其柄的天下大治。"
