      "order": 1,
      "canonicalText": "天地設，而民生之。當此之時也，民知其母而不知其父，其道親親而愛私。親親則別，愛私則險，民眾而以別險為務，則民亂。當此時也，民務勝而力征。務勝則爭，力征則訟，訟而無正，則莫得其性也。故賢者立中正，設無私，而民說仁。當此時也，親親廢，上賢立矣。",
