      "readingAid": {
        "translation": "大凡推崇仁愛的人以博愛施利為首要事務，而自命賢能的人以互相比拼智力才能高低為立身之道（以相出為道）。然而人口日益眾多而缺乏明確的法度制度約束，長久任由人們憑藉個人聰明互相爭奪出頭，就必定會重新引發巨大的社會混亂！\\n\\n因此後世聖人承接歷史發展順勢而為，創立制定了土地疆界、財物資產以及男女婚姻的明確產權歸屬界限（作為土地貨財男女之分）。產權分界確立了如果沒有強制法律制度保障是不行的，所以制定頒布了法律禁令（立禁）；法律禁令頒布了如果沒有專門執法機構去監督執行是不行的，所以設立了各級政府官職（立官）；各級官府設立了如果沒有一個統一的最高核心去領導統御是不行的，所以正式擁立了國家最高君王（立君）！\\n\\n國家君王一旦正式確立，那麼此前單純推崇個人私智的「上賢」時代就被超越廢棄，而強調尊卑秩序法治權威的「貴貴尊官」時代正式確立了！\\n\\n既然如此：那麼上古時代推崇血緣親情而偏愛私利（上世親親），中古時代推崇賢能才智而悅服仁愛（中世上賢），近世當代推崇國家權威而尊崇法治官職（下世貴貴而尊官）！推崇賢能是憑藉個人才智超越他人；而擁立君王建立法治，則是使個人的私智盲動歸於無用；推崇親情是以私人利益為準則，而確立大公中正則是使私心私情徹底無法橫行！這三種歷史階段並非彼此盲目相反矛盾，而是因為前一種社會治理模式產生了弊端、所以歷史所側重的核心價值隨之轉移更替（所重易也），時代環境局勢發生了深刻巨變、所以治理天下的客觀大道也隨之調整演進（行道異也）！所以說：成就王業的大道有著不可動搖的客觀規律準繩（王道有繩）！",
        "analysis": "【題解與上世親親中世上賢下世貴貴定分立禁立官立君人類國家與法律起源論】中國古代最為宏偉深刻的國家與法律起源進化論——系統梳理「親親（原始血緣）→上賢（部落推選）→貴貴（法治國家君主制）」之不可逆進化法則，提出產權界定（分定）、法律禁令（立禁）、官僚體制（立官）、君權國家（立君）的國家形成四步論，堪稱戰國法學之巔峰！\\n【詞義訓詁】「相出」：互相爭勝出頭；「土地男女之分」：定產權與婚姻秩序；「王道有繩」：繩，準繩規律。"
      },
      "translation": "大凡推崇仁愛的人以博愛施利為首要事務，而自命賢能的人以互相比拼智力才能高低為立身之道（以相出為道）。然而人口日益眾多而缺乏明確的法度制度約束，長久任由人們憑藉個人聰明互相爭奪出頭，就必定會重新引發巨大的社會混亂！\\n\\n因此後世聖人承接歷史發展順勢而為，創立制定了土地疆界、財物資產以及男女婚姻的明確產權歸屬界限（作為土地貨財男女之分）。產權分界確立了如果沒有強制法律制度保障是不行的，所以制定頒布了法律禁令（立禁）；法律禁令頒布了如果沒有專門執法機構去監督執行是不行的，所以設立了各級政府官職（立官）；各級官府設立了如果沒有一個統一的最高核心去領導統御是不行的，所以正式擁立了國家最高君王（立君）！\\n\\n國家君王一旦正式確立，那麼此前單純推崇個人私智的「上賢」時代就被超越廢棄，而強調尊卑秩序法治權威的「貴貴尊官」時代正式確立了！\\n\\n既然如此：那麼上古時代推崇血緣親情而偏愛私利（上世親親），中古時代推崇賢能才智而悅服仁愛（中世上賢），近世當代推崇國家權威而尊崇法治官職（下世貴貴而尊官）！推崇賢能是憑藉個人才智超越他人；而擁立君王建立法治，則是使個人的私智盲動歸於無用；推崇親情是以私人利益為準則，而確立大公中正則是使私心私情徹底無法橫行！這三種歷史階段並非彼此盲目相反矛盾，而是因為前一種社會治理模式產生了弊端、所以歷史所側重的核心價值隨之轉移更替（所重易也），時代環境局勢發生了深刻巨變、所以治理天下的客觀大道也隨之調整演進（行道異也）！所以說：成就王業的大道有著不可動搖的客觀規律準繩（王道有繩）！",
      "analysis": "【題解與上世親親中世上賢下世貴貴定分立禁立官立君人類國家與法律起源論】中國古代最為宏偉深刻的國家與法律起源進化論——系統梳理「親親（原始血緣）→上賢（部落推選）→貴貴（法治國家君主制）」之不可逆進化法則，提出產權界定（分定）、法律禁令（立禁）、官僚體制（立官）、君權國家（立君）的國家形成四步論，堪稱戰國法學之巔峰！\\n【詞義訓詁】「相出」：互相爭勝出頭；「土地男女之分」：定產權與婚姻秩序；「王道有繩」：繩，準繩規律。"
