      "order": 4,
      "canonicalText": "聖人不法古，不修今。法古則後於時，修今則塞於勢。周不法商，夏不法虞，三代異勢，而皆可以王。故興王有道，而持之異理。武王逆取而貴順，爭天下而上讓；其取之以力，持之以義。今世強國事兼併，弱國務力守；上不及虞夏之時，而下不修湯武之道。湯武之道塞，故萬乘莫不戰，千乘莫不守。此道之塞久矣，而世主莫之能開也，故三代不四。非明主莫有能聽也，今日願啟之以效。古之民樸以厚，今之民巧以偽。",
