      "id": "shang-jun-shu_ch-7_p-7",
      "chapterId": "shang-jun-shu_ch-7",
      "order": 7,
      "canonicalText": "古者民藂生而羣處亂，故求有上也。然則天下之樂有上也，將以為治也。今有主而無法，其害與無主同；有法不勝其亂，與無法同。天下不安無君，而樂勝其法，則舉世以為惑也。夫利天下之民者，莫大於治；而治莫康於立君；立君之道，莫廣於勝法；勝法之務，莫急於去姦；去姦之本，莫深於嚴刑。故王者以賞禁，以刑勸；求過不求善，藉刑以去刑。",
