      "id": "shang-jun-shu_ch-8_p-1",
      "chapterId": "shang-jun-shu_ch-8",
      "order": 1,
      "canonicalText": "凡將立國，制度不可不時也，治法不可不慎也，國務不可不謹也，事本不可不摶也。制度時，則國俗可化，而民從制。治法明，則官無邪。國務壹，則民應用。事本摶，則民喜農而樂戰。夫聖人之立法化俗，而使民朝夕從事於農也，不可不知也。夫民之從事死制也，以上之設榮名，置賞罰之明也。不用辯說私門而功立矣，故民之喜農而樂戰也。見上之尊農戰之士，而下辯說技藝之民，而賤遊學之人也，故民壹務；其家必富，而身顯於國。上開公利而塞私門，以致民力，私勞不顯於國，私門不請於君。若此而功名勸，則上令行而荒草闢，淫民止而姦無萌。治國能摶民力而壹民務者強，能事本而禁末者富。",
