        "translation": "如今世俗各國君主全都口口聲聲想要治理好百姓，然而其實際政策舉措卻反而在火上澆油助長社會動亂！這並不是君主主觀上樂於製造動亂，而是因為他們思想保守安於舊習（安其故），而根本不去審時度勢觀察時代的深刻變革（不闚於時）！\\n\\n對上盲目效法古代而導致治國道路徹底被堵塞壅塞（法古得其塞），對下苟且因循當前弊政而不知道隨時變革（不時移），既不明白世風民俗的歷史演進，又不考察治理人民的真實人情規律；所以濫施獎賞反而招致刑罰案件越發氾濫，對罪過輕描淡寫姑息放縱反而導致獎賞徹底喪失激勵作用！\\n\\n朝廷設立了刑罰而人民卻因其不公不威而不肯服從，國庫獎賞資源耗盡匱乏而奸邪作惡之徒反而越發猖獗氾濫！所以君王治理引導人民，必須堅持「以嚴明刑罰立威為先、以公正獎賞激勵為後（先刑而後賞）」的根本法治原則！",
        "analysis": "【訓詁與名物】「闚」同「窺」，觀察。「安其故」安於舊有的傳統、故步自封。「得其塞」遇到了阻塞、行不通。「不時移」不能隨著時代的變化而轉移。「多賞以致刑」因為賞賜過多過濫，導致民眾不知滿足、鋌而走險，最終觸犯刑律。「輕刑以去賞」刑罰太輕無法震懾犯罪，使得原本用來鼓勵立功的賞賜也失去了意義（大家都去犯罪獲利，沒人稀罕合法的賞賜了）。「賞匱」賞賜的物資枯竭。\\n【章法與結構】本段是對當時各國保守政治的深刻診斷。先指出病因（安故不闚時、法古得塞），接著分析具體的病理表現（多賞致刑、輕刑去賞），最後開出法家一劍封喉的猛藥（先刑而後賞）。\\n【思想與義理】此章再次強調了法家的「變法史觀」和「重刑輕賞」原則。商鞅批評了戰國時期許多君主試圖用西周的「仁政、德治（輕刑多賞）」來治理亂世的錯誤傾向。他深刻地指出，在一個人性已經極度逐利的時代（世俗之變），如果還濫用賞賜、減輕刑罰，不僅起不到教化作用，反而會刺激民眾的貪婪，導致國家財政破產（賞匱）和犯罪氾濫。因此，法治的優先級必須明確：絕對的威懾力（刑）永遠排在第一位。只有當「先刑」把社會底線牢牢守住，讓民眾不敢作亂時，「後賞」才能發揮引導他們去為國家立功（農戰）的積極作用。這是極其冷靜甚至冷酷的政治實用主義。"
