      "id": "shang-jun-shu_ch-15_p-4",
      "chapterId": "shang-jun-shu_ch-15",
      "order": 4,
      "canonicalText": "今王發明惠，諸侯之士來歸義者，今使復之三世，無知軍事。秦四境之內，陵阪丘隰不起十年徵，著於律也，足以食作夫百萬。曩者臣言曰：「意民之情，其所欲者，田宅也；晉之無有也信，秦之有餘也必，若此而民不西者，秦士戚而民苦也。」今利其田宅，復之三世。此必與其所欲，而不使行其所惡也。然則山東之民無不西者矣。且直言之謂也；不然，夫實曠虛，出天寶，而百萬事本，其所益多也，豈徒不失其所以攻乎？",
