      "readingAid": {
        "translation": "如今若君王昭彰頒布浩蕩明智的恩惠政策：凡是天下各諸侯國前來歸附投奔秦國的移民士民，立即下令給予他們祖孫三代免除兵役徭役的特大優惠（復之三世），讓他們安心耕作而無須承擔前線軍事作戰任務！\\n\\n在秦國四方邊境之內，新開墾的山丘荒坡與低窪沼澤田地，整整十年之內不徵收任何田賦農業稅（不起十年徵），並把這項優惠政策白紙黑字莊嚴寫入國家根本法律（著於律也），這足夠供應養活上百萬從事農業開荒的精壯勞動力（食作夫百萬）！\\n\\n此前臣就說過：「體察百姓的人情人性，內心所渴望追求的無非是田地住宅；三晉人多無田是真，秦國地廣有餘是實，此前百姓不肯西遷，完全是因為秦國官吏嚴苛而百姓太苦。」如今我們把肥沃田宅獎勵給他們，給予其三代免除兵役徭役的特惠；這正是完全滿足給予了他們所最渴望追求的利益（必與其所欲），而且免除了他們所最畏懼害怕的兵役勞役（不使行其所惡）！\\n\\n如果真能這樣實施，那麼東方崤山以東的廣大百姓就必定會如同潮水一般爭相向西遷徙歸附秦國（山東之民無不西者矣）！這完全是符合客觀規律的實話實說啊；如果不這樣做，那麼秦國廣袤的荒蕪土地如何充實？大地的無盡寶藏如何開發？讓上百萬移民專心在秦國從事農業生產，這對秦國綜合國力所帶來的巨大增益是無可估量的，這哪裡僅僅是保持我們在戰場上的進攻優勢而已呢！",
        "analysis": "【題解與背景】\\n本段選自《商君書》〈徠民〉第 122 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「今王發明惠諸侯之士來歸義者今使復之三世無知軍……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「今」、「王」、「發」、「明」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《商君書》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
      },
      "translation": "如今若君王昭彰頒布浩蕩明智的恩惠政策：凡是天下各諸侯國前來歸附投奔秦國的移民士民，立即下令給予他們祖孫三代免除兵役徭役的特大優惠（復之三世），讓他們安心耕作而無須承擔前線軍事作戰任務！\\n\\n在秦國四方邊境之內，新開墾的山丘荒坡與低窪沼澤田地，整整十年之內不徵收任何田賦農業稅（不起十年徵），並把這項優惠政策白紙黑字莊嚴寫入國家根本法律（著於律也），這足夠供應養活上百萬從事農業開荒的精壯勞動力（食作夫百萬）！\\n\\n此前臣就說過：「體察百姓的人情人性，內心所渴望追求的無非是田地住宅；三晉人多無田是真，秦國地廣有餘是實，此前百姓不肯西遷，完全是因為秦國官吏嚴苛而百姓太苦。」如今我們把肥沃田宅獎勵給他們，給予其三代免除兵役徭役的特惠；這正是完全滿足給予了他們所最渴望追求的利益（必與其所欲），而且免除了他們所最畏懼害怕的兵役勞役（不使行其所惡）！\\n\\n如果真能這樣實施，那麼東方崤山以東的廣大百姓就必定會如同潮水一般爭相向西遷徙歸附秦國（山東之民無不西者矣）！這完全是符合客觀規律的實話實說啊；如果不這樣做，那麼秦國廣袤的荒蕪土地如何充實？大地的無盡寶藏如何開發？讓上百萬移民專心在秦國從事農業生產，這對秦國綜合國力所帶來的巨大增益是無可估量的，這哪裡僅僅是保持我們在戰場上的進攻優勢而已呢！",
      "analysis": "【題解與復之三世無知軍事不起十年徵著於律食作夫百萬山東之民無不西移民特區法案】中國古代最早最具前瞻性的「移民特區優惠法案」——「復之三世無知軍事、十年免徵著於律」，以土地與免稅特惠實施跨國人口虹吸，引進百萬勞動力。"
