      "translation": "此前秦國面臨的最大戰略困境與隱患在於：一旦大舉出動軍隊征討敵國，國內農田缺乏勞力就會導致國家財政物資陷入貧困匱乏；而如果全軍回國安居從事農業生產，外部敵國又會趁機獲得喘息休整重整旗鼓，這正是君王此前在戰略上無法兼顧兩全的兩難困境啊（不能兩成也）！正因如此秦國雖然四代交戰獲勝，而天下諸侯卻始終未能徹底臣服！\\n\\n如今如果實施新政：讓秦國原有的老秦人部隊專門負責對外征戰打擊強敵（以故秦事敵），而讓新遷徙歸附的外來移民專門在國內從事農業生產開荒墾殖（使新民作本）！\\n\\n這樣一來，秦國主力軍隊縱然在國外長期作戰駐紮數百天（兵雖百宿於外），而國內後方的農業耕作生產卻絲毫不會耽誤分秒農時（境內不失須臾之時），這正是實現「國家既富裕充盈而軍隊又無比強大」兩全其美兼備並成的最高宏偉戰略奇效啊（富強兩成之效也）！",
