      "id": "shang-jun-shu_ch-15_p-7",
      "chapterId": "shang-jun-shu_ch-15",
      "order": 7,
      "canonicalText": "且周軍之勝，華軍之勝，長平之勝，秦所亡民者幾何，民客之兵不得事本者幾何，臣竊以為不可數矣。假使王之群臣，有能用之，費此之半，弱晉強秦，若三戰之勝者，王必加大賞焉。今臣之所言，民無一日之繇，官無數錢之費，其弱晉強秦有過三戰之勝；而王猶以為不可，則臣愚不能知已。",
