      "readingAid": {
        "translation": "況且回顧周之戰的勝利、華陽之戰的勝利、以及長平之戰的勝利，秦國自身在慘烈大戰中傷亡陣亡的將士百姓究竟有多少？被征發服役而長年無法在後方從事農業生產的士兵役夫究竟有多少？臣私下認為其代價之沉重簡直無法計算啊！\\n\\n假使君王的滿朝群臣之中，有人能夠提出某種良策，耗費的代價只有上述大戰的一半，而能夠達成「削弱三晉、強大秦國」如同取得三大戰役全勝的效果，君王必定會對他予以破格重賞！如今臣所提出的招徠移民墾荒國策，秦國百姓用不著承擔多一天額外徭役勞役（民無一日之繇），朝廷官府用不著額外耗費分文多餘開支（官無數錢之費），而其「削弱三晉、強大秦國」的長遠戰略成效卻遠遠超過了三大戰役全勝的輝煌成果；如果君王依然猶豫認為不可推行，那麼臣實在愚鈍再也無法理解了！",
        "analysis": "【題解與背景】\\n本段選自《商君書》〈徠民〉第 125 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「且周軍之勝華軍之勝長平之勝秦所亡民者幾何民客……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「且」、「周」、「軍」、「勝」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《商君書》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
      },
      "translation": "況且回顧周之戰的勝利、華陽之戰的勝利、以及長平之戰的勝利，秦國自身在慘烈大戰中傷亡陣亡的將士百姓究竟有多少？被征發服役而長年無法在後方從事農業生產的士兵役夫究竟有多少？臣私下認為其代價之沉重簡直無法計算啊！\\n\\n假使君王的滿朝群臣之中，有人能夠提出某種良策，耗費的代價只有上述大戰的一半，而能夠達成「削弱三晉、強大秦國」如同取得三大戰役全勝的效果，君王必定會對他予以破格重賞！如今臣所提出的招徠移民墾荒國策，秦國百姓用不著承擔多一天額外徭役勞役（民無一日之繇），朝廷官府用不著額外耗費分文多餘開支（官無數錢之費），而其「削弱三晉、強大秦國」的長遠戰略成效卻遠遠超過了三大戰役全勝的輝煌成果；如果君王依然猶豫認為不可推行，那麼臣實在愚鈍再也無法理解了！",
      "analysis": "【題解與周華長平之勝代價反思民無一日之繇官無數錢之費戰略成本效益極致】深刻對比軍事決戰的高昂傷亡成本與和平移民政策的零成本高效益——「民無一日之繇，官無數錢之費」，其削弱三晉之功遠超長平之戰。"
