      "order": 8,
      "canonicalText": "齊人有東郭敞者，猶多願，願有萬金。其徒請賙焉，不與，曰：「吾將以求封也。」其徒怒而去之宋，曰：「此無益於愛也，故不如與之利也。」今晉有民，而秦愛其復，此愛非其有以失其有也，豈異東郭敞之愛非其有而失其徒乎？",
