      "translation": "齊國有一個名叫東郭敞的人，平日裡充滿了不切實際的非分奢望，日夜夢想著自己能發財擁有一萬兩黃金。他手下的門徒學生遭遇窮困前來請求他給予周濟救濟（請賙焉），東郭敞卻一毛不拔不肯給予，還自吹自擂說道：「我這些錢將來是要用來向國君謀求封侯拜相的！」他的門徒聽後大為憤怒紛紛拋棄他轉而投奔宋國，並說道：「這種空洞虛妄的吝嗇對我們毫無益處，還不如去投奔能給我們帶來實質利益的明主！」\\n\\n如今三晉各國明明擁有龐大的人口資源，而秦國君臣卻過分吝嗇那一丁點免稅免役的優惠待遇（秦愛其復）；這正是在吝嗇自己本來就未曾真正擁有的東西、結果反而白白喪失了本來可以唾手可得的巨大戰略利益（愛非其有以失其有）！這跟齊國東郭敞因為吝嗇虛幻的萬金而最終徹底眾叛親離失去全體門徒，難道有任何實質區別嗎？",
      "analysis": "【題解與東郭敞空想萬金愛非其有以失其有戰略吝嗇批判之深刻隱喻】以齊人東郭敞之生動寓言，辛辣諷刺秦國守舊官吏在移民政策上的戰略短視與「愛非其有以失其有」之愚蠢，闡發唯有大膽讓利方能聚天下之民的宏偉格局。"
