      "canonicalText": "且古有堯舜，當時而見稱；中世有湯武，在位而民服。此四王者，萬世之所稱以為聖王者也。然其道猶不能取用於後。今復之三世，而三晉之民可盡也，是非王賢力今時，而使後世為王用乎？然則非聖別說，而聽聖人難也。",
