      "readingAid": {
        "translation": "況且上古時代有堯舜二帝，在當時備受天下稱道；中古時代有商湯周武，在位之際天下萬民由衷臣服。這四位偉大君王，乃是萬世歷代共同推崇尊稱的最高聖明聖王啊！然而他們的具體歷史法度與道路，尚且不能機械照搬套用於後世變革的時代！\\n\\n如今只要給予外來移民三代免除兵役徭役的優惠，三晉數以百萬計的人口資源就能全部被秦國徹底吸收轉化囊括無遺！這難道不正是君王在當代展現無雙賢能實力、並使未來後世千秋萬代的人口皆能為大秦所驅使任用的宏偉偉業嗎？既然如此那麼何必聽信那些脫離實際的迂腐異端邪說呢？然而世間昏庸之主想要真正聽懂並踐行聖人的深邃大道，實在是太艱難了啊！",
        "analysis": "【題解與背景】\\n本段選自《商君書》〈徠民〉第 127 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「且古有堯舜當時而見稱中世有湯武在位而民服此四……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「且」、「古」、「有」、「堯」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《商君書》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
      },
