      "canonicalText": "聖人之為國也：壹賞，壹刑，壹教。壹賞則兵無敵，壹刑則令行，壹教則下聽上。夫明賞不費，明刑不戮，明教不變，而民知於民務，國無異俗。明賞之猶，至於無賞也；明刑之猶，至於無刑也；明教之猶，至於無教也。",
