      "readingAid": {
        "translation": "得道聖人治理國家的大道：在於推行「專一的獎賞（壹賞）、專一的刑罰（壹刑）、專一的教化（壹教）」！\\n\\n獎賞途徑專一於軍功那麼軍隊在天下就所向無敵（壹賞則兵無敵），刑罰標準專一嚴明那麼國家法令就能徹底暢行（壹刑則令行），社會教化專一於農戰那麼下層民眾就能完全聽命於朝廷君王（壹教則下聽上）！\\n\\n獎賞制度公開透明那麼國家財政就用不著耗費無度（明賞不費），刑法條文清晰嚴肅那麼社會就無須頻繁濫施殺戮（明刑不戮），教化方向堅定專一那麼國家政策就無須朝令夕改（明教不變）；廣大民眾人人深知自己所應恪盡的農戰本職，全國上下沒有各行其是的怪異陋習！\\n\\n獎賞制度真正清明透明的最高境界，最終能達到甚至用不著刻意施加獎賞而天下自然奮勇向前（至於無賞）；\\n刑罰制度真正嚴肅威嚴的最高境界，最終能達到全社會沒有人敢於犯罪而根本無須動用刑罰（至於無刑）；\\n社會教化真正深入人心的最高境界，最終能達到天下民眾自覺化育遵循秩序而根本用不著繁瑣說教（至於無教）！",
        "analysis": "【主題與背景】本段選自《商君書・賞刑》。論述「壹賞、壹刑、壹教」的法家核心賞罰體系與司法公正原則。歷史上記錄了秦國實行法家變法、走向中央集權與帝國統一的理論與制度建構。\\n【詞義與名物】段落中涵括「賞刑」相關關鍵名詞，如「法」、「信」、「權」、「耕戰」、「錯法」、「壹賞」等，體現秦國法律體系精密的制度設計。\\n【思想與篇章】《商君書》此段強調「法者，國之權衡也」，通過嚴密法律與權力集中，打破舊貴族世襲特權，將國家資源全數注入農耕與軍事，為戰國時期法家變法實踐提供了深刻的戰略引領。"
      },
      "translation": "得道聖人治理國家的大道：在於推行「專一的獎賞（壹賞）、專一的刑罰（壹刑）、專一的教化（壹教）」！\\n\\n獎賞途徑專一於軍功那麼軍隊在天下就所向無敵（壹賞則兵無敵），刑罰標準專一嚴明那麼國家法令就能徹底暢行（壹刑則令行），社會教化專一於農戰那麼下層民眾就能完全聽命於朝廷君王（壹教則下聽上）！\\n\\n獎賞制度公開透明那麼國家財政就用不著耗費無度（明賞不費），刑法條文清晰嚴肅那麼社會就無須頻繁濫施殺戮（明刑不戮），教化方向堅定專一那麼國家政策就無須朝令夕改（明教不變）；廣大民眾人人深知自己所應恪盡的農戰本職，全國上下沒有各行其是的怪異陋習！\\n\\n獎賞制度真正清明透明的最高境界，最終能達到甚至用不著刻意施加獎賞而天下自然奮勇向前（至於無賞）；\\n刑罰制度真正嚴肅威嚴的最高境界，最終能達到全社會沒有人敢於犯罪而根本無須動用刑罰（至於無刑）；\\n社會教化真正深入人心的最高境界，最終能達到天下民眾自覺化育遵循秩序而根本用不著繁瑣說教（至於無教）！",
      "analysis": "【題解與賞刑篇開篇壹賞壹刑壹教明賞不費明刑不戮至無賞無刑無教法家最高境界】《商君書》（賞刑第十七）開篇總綱——提出「壹賞、壹刑、壹教」三位一體法治體系，論述「明賞不費、明刑不戮、明教不變」，最終達成「無賞、無刑、無教」的天下大治極致境地。\\n【詞義訓詁】「壹賞壹刑壹教」：賞刑教化皆專一於農戰；「明刑不戮」：刑律嚴明震懾犯罪，使人不敢犯法，從而無須殺戮。"
