      "canonicalText": "昔湯封於贊茅，文王封於岐周，方百里。湯與桀戰於鳴條之野，武王與紂戰於牧野之中，大破九軍，卒裂土封諸侯，士卒坐陳者里有書社，車休息不乘，從馬華山之陽，從牛於農澤，從之老而不收，此湯武之賞也。故曰：贊茅岐周之粟，以賞天下之人，不人得一升；以其錢賞天下之人，不人得一錢。故曰：百里之君，而封侯其臣，大其舊。",
