      "readingAid": {
        "translation": "從前商湯最初被封在贊茅之地，周文王最初被封在岐山周原之地，疆域不過方圓百里而已。商湯與夏桀決戰於鳴條之野，周武王與商紂決戰於牧野之中，大破敵軍九軍主力，最終分封天下土地封賞全體諸侯；戰場上排開陣列奮勇殺敵的立功將士，人人都能在鄉里分得屬於自己的田宅與書社產權；戰車全部停歇刀槍入庫不再乘用，戰馬全部放歸於華山南麓自由奔馳（放馬華陽），耕牛全部放牧於桃林原野任其耕作繁殖，任憑牠們自然老去而不再強行徵發，這正是商湯與周武王所施加的至高重賞啊！\\n\\n所以說：如果單純依靠贊茅與岐周原有那一塊百里狹小土地上出產的微薄糧食，用來賞賜全天下立功將士，那麼分到每個人頭上甚至連一升糧食都分不到；如果單純用那裡原有的微薄錢財來賞賜天下之人，分到每個人頭上甚至連一枚銅錢都分不到！所以古語說道：原本僅僅統治百里封地的弱小君主，最終卻能夠裂土封侯重賞全體功臣將士，正是因為他們打破了舊有狹隘格局、通過戰勝強敵奪取了全天下的浩瀚財富來重賞功臣啊！",
        "analysis": "【題解與背景】\\n本段選自《商君書》〈賞刑〉第 130 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「昔湯封於贊茅文王封於岐周方百里湯與桀戰於鳴條……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「昔」、「湯」、「封」、「贊」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《商君書》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
      },
