      "analysis": "【題解與商湯贊茅周文岐周鳴條牧野大破九軍放馬華陽善因天下之貨以賞天下之人】以商湯滅夏、武王伐紂之歷史典範，雄辯論證以小博大、因敵制勝的重賞哲學——百里之君能封侯其臣，全在於善用天下之財富獎賞天下之立功將士。"
