      "canonicalText": "自士卒坐陳者，里有書社。賞之所加，寬於牛馬者，何也？善因天下之貨，以賞天下之人。故曰：「明賞不費。」湯武既破桀紂，海內無害，天下大定，築五庫，藏五兵，偃武事，行文教，倒載干戈，搢笏作為樂以申其德。當此時也，賞祿不行，而民整齊。故曰：「明賞之猶，至於無賞也。」",
