      "order": 5,
      "canonicalText": "所謂壹刑者，刑無等級。自卿相將軍以至大夫庶人，有不從王令，犯國禁，亂上制者，罪死不赦。有功於前，有敗於後，不為損刑。有善於前，有過於後，不為虧法。忠臣孝子有過，必以其數斷。守法守職之吏，有不行王法者，罪死不赦，刑及三族。同官之人，知而訐之上者，自免於罪。無貴賤，尸襲其官長之官爵田祿。故曰：「重刑連其罪，則民不敢試。」民不敢試，故無刑也。夫先王之禁刺殺，斷人之足，黥人之面，非求傷民也，以禁姦止過也。故禁姦止過，莫若重刑。刑重而必得，則民不敢試，故國無刑民。國無刑民，故曰：「明刑不戮。」",
