      "canonicalText": "晉文公欲明刑以親百姓，於是合諸侯大夫於侍千宮。顛頡後至，請其罪。君曰：「用事焉，」吏遂斷顛頡之脊以殉。晉國之士，稽焉皆懼，曰：「顛頡之有寵也，斷以殉，況於我乎？」舉兵伐曹及五鹿，反鄭之埤，東衛之畝，勝荊人於城濮。三軍之士，止之如斬足，行之如流水。三軍之士，無敢犯禁者。故一假道重輕於顛頡之脊，而晉國治。",
