        "translation": "春秋時期晉文公想要整頓嚴明國家軍法以團結親近全體百姓，於是在侍千宮大會全體諸侯大夫與將領。重臣顛頡無故遲到後至，執法官向晉文公請示如何治罪。晉文公嚴肅下令道：「嚴格依照軍法處置！」執法官於是當場斬斷了顛頡的脊樑骨並懸首示眾以正軍紀（斷顛頡之脊以殉）！\\n\\n晉國全體將士得知後無不震驚敬畏叩首，紛紛私下說道：「像顛頡這樣深得國君寵信的元勳重臣，犯了軍法尚且被斬斷脊樑處死示眾，又何況我們這些普通士卒呢？」\\n\\n隨後晉文公大舉出兵征討曹國與五鹿要塞，迫使鄭國歸還侵佔的城邑，向東奪取衛國的田地，最終在著名的城濮之戰中大破楚國強大主力！晉國全軍三軍將士：下令停止前進時部隊肅立原地如同被砍斷雙足一般紋絲不動（止之如斬足），下令衝鋒前進時部隊勢不可擋如同滔滔江水奔騰向前（行之如流水）！全軍將士沒有一個人敢於違抗軍法禁令！所以晉文公僅僅是在功臣顛頡的脊樑上動用了一次軍法嚴刑，就使整個晉國實現了軍紀嚴明的大治並成就了春秋中原霸業！",
