        "translation": "從前西周開國元勳周公旦依法誅殺了叛亂的親兄弟管叔，流放了同謀的親兄弟霍叔，莊嚴宣告道：「這是因為他們觸犯了國家神聖法律禁令啊（犯禁者也）！」天下萬民聽後無不心悅誠服說道：「連周公自己的至親骨肉親兄弟犯了罪過尚且依法嚴懲絕不包庇偏袒，又何況對待關係疏遠的普通人呢？」\\n\\n所以天下萬民深刻知曉周朝朝廷執法如山、在王室太廟庭院中同樣嚴格依法動用刀鋸刑具，因此四海之內實現了天下大治！所以說：「嚴明刑法推行貫徹的最高境界，最終能自然達到全天下沒有人敢於犯罪而根本無須動用刑罰的崇高天下大治啊（明刑之猶至於無刑也）！」",
