      "id": "shang-jun-shu_ch-17_p-8",
      "chapterId": "shang-jun-shu_ch-17",
      "order": 8,
      "canonicalText": "所謂壹教者，博聞辯慧，信廉禮樂，修行羣黨，任譽清濁，不可以富貴，不可以評刑，不可獨立私議以陳其上。堅者破，銳者挫。雖曰聖知巧佞厚樸，則不能以非功罔上利。然富貴之門，要在戰而已矣。彼能戰者，踐富貴之門；強梗者，有常刑而不赦。是父兄、昆弟、知識、婚姻、合同者，皆曰：「務之所加，存戰而已矣。」夫故當壯者務於戰，老弱者務於守；死者不悔，生者務勸。此臣之所謂壹教也。民之慾富貴也，共闔棺而後止。而富貴之門，必出於兵。是故民聞戰而相賀也；起居飲食所歌謠者，戰也。此臣之所謂「明教之猶，至於無教也。」",
