      "readingAid": {
        "translation": "這正是臣所系統總結的「壹賞、壹刑、壹教」三大核心支柱相輔相成的參驗教化體系（參教也）！\\n\\n聖人並非事無巨細通曉宇宙萬事萬物，而是牢牢掌握了決定萬物成敗的根本要領（知萬物之要）；所以他治理國家，只要精準抓住這個核心要領就能從容駕馭調動天下萬事萬物！因此政令條文簡約精練而取得的治國成效卻無比宏大卓越（寡教而多功）！\\n\\n聖人治理天下的法治大道，原理原則極其簡單明了容易理解（易知），然而在現實利益面前排除阻力堅定貫徹執行卻極其需要鋼鐵意志（難行也）！正因如此聖人治國用不著額外隨意增加繁瑣法規，庸碌君主也絕不可隨意廢棄根本法度。依據法律處決罪犯非殘暴不仁，依據戰功重賞將士也絕非出於個人私恩仁慈，這完全是因為國家法律法度客觀透明昭彰啊！\\n\\n聖人完全依據實際戰功來授予各級官職、頒發爵位，所以真正身懷真才實學的賢能之士永遠不用擔心自己被埋沒忽視（賢者不憂）；聖人絕不隨意寬宥過失罪責、絕不隨意赦免法定制裁，所以一切奸邪犯罪在源頭上就根本無從滋生興起！得道聖人治理天下的終極精髓，唯在於精審法度、堅定不移推行「作壹」這一根本大道罷了！",
        "analysis": "【題解與背景】\\n本段選自《商君書》〈賞刑〉第 136 節。屬於古代法家治術代表性經典，記述先賢關於主張法術勢結合、富國強兵、賞罰分明與明法審令之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「此臣之所謂參教也聖人非能通知萬物之要也故其治……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「此」、「臣」、「所」、「謂」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《商君書》知行合一與經世致用之哲理觀念，反映法家先賢關於制度建設、行政效能與嚴明法令之經世智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"
      },
      "translation": "這正是臣所系統總結的「壹賞、壹刑、壹教」三大核心支柱相輔相成的參驗教化體系（參教也）！\\n\\n聖人並非事無巨細通曉宇宙萬事萬物，而是牢牢掌握了決定萬物成敗的根本要領（知萬物之要）；所以他治理國家，只要精準抓住這個核心要領就能從容駕馭調動天下萬事萬物！因此政令條文簡約精練而取得的治國成效卻無比宏大卓越（寡教而多功）！\\n\\n聖人治理天下的法治大道，原理原則極其簡單明了容易理解（易知），然而在現實利益面前排除阻力堅定貫徹執行卻極其需要鋼鐵意志（難行也）！正因如此聖人治國用不著額外隨意增加繁瑣法規，庸碌君主也絕不可隨意廢棄根本法度。依據法律處決罪犯絕不是殘暴不仁，依據戰功重賞將士也絕非出於個人私恩仁慈，這完全是因為國家法律法度客觀透明昭彰啊！\\n\\n聖人完全依據實際戰功來授予各級官職、頒發爵位，所以真正身懷真才實學的賢能之士永遠不用擔心自己被埋沒忽視（賢者不憂）；聖人絕不隨意寬宥過失罪責、絕不隨意赦免法定制裁，所以一切奸邪犯罪在源頭上就根本無從滋生興起！得道聖人治理天下的終極精髓，唯在於精審法度、堅定不移推行「作壹」這一根本大道罷了！",
      "analysis": "【題解與參教體系知萬物之要寡教多功殺人不為暴賞人不為仁審壹而已賞刑篇終篇大結尾】《商君書》（賞刑篇）史詩級總結——「寡教而多功」、「殺人不為暴、賞人不為仁（純粹法治客觀主義）」，以「審壹」圓滿總結法家富國強兵的最高制度架構。"
