      "order": 1,
      "canonicalText": "昔者昊英之世，以伐木殺獸，人民少而木獸多。黃帝之世，不麛不卵，官無常，官無常，官無常，民皆爭利。少昊之世，民好爭而無制，顓頊之世，民好殺而無禁。故聖人承之，作為法度，以定其亂。",
