      "readingAid": {
        "translation": "從前昊英氏的時代，人們砍樹、捕殺禽獸；當時人口少而草木禽獸多。到了黃帝時代，不捕殺幼獸，不取鳥卵；官府沒有徵調百姓供應喪具的制度，死後也不得使用外棺。這些做法雖然不同，卻都能成就王業，原因在於時勢不同。神農時代，男子耕種供給食物，女子紡織製作衣服，不用刑罰政令便能治理，不發動武力也能稱王。神農死後，社會變成強者制伏弱者、多數欺凌少數。因此黃帝制定君臣上下的名分、父子兄弟的禮節和夫婦婚配的規範；對內施用刑罰，對外動用軍隊，因為時勢已經改變。由此看來，神農的能力並不高過黃帝；他的名聲之所以受尊崇，是因為措施適合當時。所以，用戰爭消除戰爭，即使作戰也可以；用殺戮消除殺戮，即使殺人也可以；用刑罰消除刑罰，即使施行重刑也可以。",
        "analysis": "本段先以昊英、神農、黃帝三個傳說時代建立「治法隨時而變」的歷史觀，再推出「以戰去戰、以殺去殺、以刑去刑」的結論。「不麛不卵」指不獵幼獸、不取鳥卵；「槨」是棺外的套棺。末三句是本篇重刑論的綱領：作者把戰爭與刑罰說成終止戰亂、刑罰的手段。這是《商君書》的政治主張，不宜在白話中改寫成普遍真理；其推論是否成立，仍須與實際後果及倫理界限分開評估。"
      },
      "translation": "遠古昊英氏統治時代，人類依託砍伐樹木、獵殺野獸維持生存，當時人口稀少而山林野獸極其眾多。黃帝統治時代，保護幼獸幼鳥不獵取幼鹿不掏鳥蛋（不麛不卵），然而各級官職缺乏恆常法度規範，民眾紛紛爭奪自然資源。少昊統治時代，民眾喜好爭鬥而缺乏制度約束；顓頊統治時代，民眾喜好殘殺而缺乏法律禁令！因此得道聖人順應歷史發展大勢順勢而為，創立制定了客觀法律法度（作為法度），用以平定天下爭端動亂！",
      "analysis": "【題解與畫策篇開篇人類遠古文明史觀黃帝顓頊作為法度定亂法家歷史唯物主義】《商君書》（畫策第十八）開篇——考察上古人類生存環境與衝突演進史，論證法律法度乃歷史發展到一定階段為平息爭端衝突而必然產生的客觀產物。\\n【詞義訓詁】「畫策」：謀劃制定富國強兵克敵制勝之最高戰略決策；「不麛不卵」：麛，音迷，幼鹿；保護生態資源。"
