      "analysis": "【題解與重治重亂法可在賢打破階級世襲客觀選官體系】系統論述制度與人才的良性互動，以客觀法度選拔實幹賢能，打破特權階級藩籬，使「官無常貴，民無常賤」之社會流動機制得以全面落實。"
