      "translation": "所謂「治理清明的聖主手下用不著標榜個別捨身忘死的孤立忠臣，真正慈愛仁德的父親家中用不著刻意彰顯個別受盡委屈的孝子（治主無忠臣慈父無孝子）」。\\n\\n國家治理不追求虛偽空洞的世俗好話善言，君臣上下人人皆依據客觀法律相互監督考察（以法相司），依據朝廷法令相互端正糾錯（命相正）！全體君臣百姓既然都能在健全法制軌道上各司其職、互相監督糾正，那麼社會秩序自然井井有條，自然用不著在體制崩潰之際再去期盼個別道德英雄去盡忠盡孝了！",
