      "translation": "在國家四方邊境之內（四境之內），全體成年男子與婦女的名字全部嚴格登記在朝廷戶籍簿冊之上（皆有名於上）：新出生的嬰兒立即登記造冊（生者著），逝去死亡的人口及時銷除戶籍（死者削）。\\n\\n身有軍功爵位的人如果企圖私下將爵位轉讓贈予沒有爵位的人，法律嚴格禁止（不得）；沒有爵位的人如果企圖向有爵者私下乞求買賣爵位，法律絕對禁止！朝廷軍功爵位絕對不可用金錢私下購買，也絕對不可能偽造假冒！",
      "analysis": "【題解與境內篇開篇戶籍生著死削爵位不可買不可偽二十等軍功爵律法規範】《商君書》（境內第十九）秦國軍功爵制實操法典開篇——確立嚴格的全民戶籍管理，嚴禁爵位私相買賣轉讓與偽造，確保軍功爵位的神聖性。\\n【詞義訓詁】「境內」：秦國全境軍制法令實操章程；「生者著死者削」：動態戶籍台賬。"
