      "translation": "引導民眾向善守法社會就能和睦安寧，給予民眾切實耕戰利益民眾就能甘心為國效命；為國效命國家就能承擔歷史重任，光有一團和氣而缺乏耕戰實力國家財政就會陷入匱乏；國家能承擔歷史重任那麼政治力量就能無比雄厚充沛！\\n\\n朝廷如果捨棄客觀法律而憑藉個人的主觀聰明心計去治理天下，那麼天下百姓就會投機取巧喜好奸詐而不再肯為國家付出實力汗水。所以聖明君王審慎嚴明法度以統御治理萬民！",
