      "analysis": "【題解與法有民安其次主操權利主貴多變民貴專一君民主客分工體系】界定君王與國民的治理分工——君王主掌策略變革與名利權柄以應對強敵，民眾主掌遵紀守法與專一於農戰以侍奉朝廷。"
