        "translation": "人口眾多、軍隊強盛，是成就帝王事業的重要資本；但若沒有明確法律加以維持，便與危亡相鄰。所以英明君主仔細考察法制。國境內的百姓沒有偏邪放縱之心，遊居不事生產的人被迫投入戰陣，萬民努力從事農耕，這些現象都可用來判斷法律是否真正發生作用。",
        "analysis": "「大資」是重要憑藉，不是有了人口軍隊便必然成功。「辟淫」指偏邪越軌；「游處之士」指脫離耕戰、遊居求仕或議論的人；「疾」是努力、急切。作者用三項可觀察結果檢驗法：民眾服從、遊士參戰、全民務農。這種結果導向的制度觀值得辨識，但其指標只有統治動員效率，未衡量百姓福祉、權利與政策錯誤成本。"
