      "readingAid": {
        "translation": "百姓對外承擔的事，沒有比作戰更艱難的，所以寬鬆的法令不能使他們做好戰爭準備。什麼叫寬鬆的法令？就是賞賜少、刑威薄弱，而旁門道路又沒有堵塞。什麼叫旁門道路？就是善辯有智的人受到尊貴，四處求官的人得到任用，憑文章學問取得的私人聲名得以顯揚。這三條路若不堵塞，百姓便不肯作戰，國事也會失敗。賞賜少，服從命令者無利可得；刑威薄，違犯命令者也不受損害。既然開放旁門引誘百姓，卻又想用輕法驅使他們作戰，就像設法捕鼠，卻拿貓來作誘餌，豈不是近於荒謬？所以想讓百姓作戰，必須使用嚴重的法令：賞賜一定要多，刑威一定要嚴，旁門一定要堵塞；善辯有智者不受尊貴，游宦者不被任用，文學造成的私人聲名不獲顯揚。賞多威嚴，百姓看到作戰所得的賞賜豐厚，便忘記死亡；看到不戰所受的羞辱，便覺得活著痛苦。賞賜使他們忘死，刑威使苟活痛苦，旁門又被封閉；以此迎敵，就像用百石強弩射擊風中落葉，哪有不能攻陷的道理？",
        "analysis": "「外事」專指對外戰爭，與下段國內農業相對。「淫道」是耕戰爵賞之外的仕進與成名途徑；「文學」在此指典籍、文章之學，不能直接等同現代文學。「設鼠而餌以狸」意謂要捕鼠卻以貓作餌：一面用游宦、私名吸引人才離開戰場，一面又要求全民作戰，政策自相矛盾。末段不是客觀描述士兵心理，而是作者主張用重賞、嚴刑和社會封鎖，使戰死比拒戰更可接受。白話忠實呈現其激勵邏輯，解析同時指出其以羞辱和死亡威脅塑造選擇的強制性。"
      },
      "translation": "天下百姓所承擔的對外事務，沒有比軍事作戰更為艱難危險的了（莫難於戰），所以寬鬆軟弱的輕法是絕對無法應對戰略戰備需要的！什麼叫做「輕法」呢？就是朝廷賞賜微薄而法律威嚴不足，百姓在戰場上根本不肯為君王所驅使效命！所以聖明君王必定實施嚴厲的重刑與極其豐厚的軍功賞賜（重刑厚賞），用以激發調動全體人民在戰場上奮勇殺敵！",
      "analysis": "【題解與外內篇開篇外事莫難於戰輕法不可備重刑厚賞以戰其民對外戰略】《商君書》（外內第二十二）開篇——論述對外戰爭的高風險性，提出必須以「重刑厚賞」激發部隊戰鬥力。\\n【詞義訓詁】「外內」：外指軍事對外征戰，內指農業國內耕作；「輕法」：刑罰寬鬆、賞賜微薄之軟弱制度。"
