        "translation": "百姓在國內從事的工作，沒有比農耕更辛苦的，所以寬鬆的治理不能驅使他們務農。什麼叫寬鬆的治理？就是農民貧窮而商人富有，工藝技術者獲利，脫離生產而生活的人眾多。農民用力最苦，所得卻不如商人和工匠。假如能使商人、工匠不再繁多，要國家不富也辦不到。所以說，想使農民和國家富足，境內糧價必須提高，對不務農者徵收的賦稅必須增多，市場收益的租稅必須加重，使百姓不得不擁有田地。沒有田地的人不得不買糧；糧價高，耕田者便有利，耕田有利，從事農業的人便增多。",
