      "order": 4,
      "canonicalText": "故治國之制，民不得避罪，如目不能以所見遁心。今亂國不然，恃多官眾吏。吏雖眾，事同體一也。夫事同體一者，相監不可。且夫利異而害不同者，先王所以為保也。",
