      "order": 6,
      "canonicalText": "夫微妙意志之言，上智之所難也。夫不待法令繩墨而無不正者，千萬之一也，故聖人以千萬治天下。故夫智者而後能知之，不可以為法，民不盡智。賢者而後知之，不可以為法，民不盡賢。故聖人為法，必使之明白易知。名正，愚智遍能知之。為置法官，置主法之吏，以為天下師，令萬民無陷於險危。故聖人立天下而無刑死者，非不刑殺也，法令明白易知，為置法官吏為之師以道之知。萬民皆知所避就；避禍就福，而皆以自治也。故明主因治而治之，故天下大治也。",
